INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT159-S3-Q1$batch09$, 159, 3, 1, $batch09$Principle-Strengthen$batch09$, $batch09$Critic: While the political message in this short story is interesting enough that the author could have based an essay, or a different short story, around that message alone, it should not have been included in this story. The story’s primary focus is humor, and the political message distracts from the story’s humorous effect.$batch09$, $batch09$Which one of the following principles, if valid, most strongly supports the critic’s reasoning?$batch09$, $batch09$B$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT159-S3-Q1$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$Authors should not convey political messages in their short stories.$batch09$, $batch09$Too Strong$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT159-S3-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$Nothing in a short story should distract from the story’s primary focus.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT159-S3-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$Writers should not risk alienating readers who disagree with them politically.$batch09$, $batch09$Out of Scope$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT159-S3-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$Political messages need to be developed differently in essays than in short stories.$batch09$, $batch09$Not the Reasoning$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT159-S3-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$A short story’s political message is irrelevant to its artistic merit.$batch09$, $batch09$Not the Reasoning$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT159-S3-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT159-S3-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$The political message shouldn't have been included in this short story.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$The story's primary focus is humor, and the political message distracts from the humor.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The critic doesn't object to the message itself. The critic even says it could carry a whole essay or a different story. The problem is that here it pulls attention from the story's main point. The principle needs to say that whatever distracts from a story's primary focus doesn't belong in it.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Nothing in a story should distract from its primary focus.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT159-S3-Q1$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This bans political messages in all short stories. The critic says the message could have anchored a different short story, so A contradicts the critic, and it ignores the reason, distraction.$batch09$), ($batch09$B$batch09$, $batch09$The political message distracts from the humor, which is the primary focus. B says nothing should do that, so the message should have been left out.$batch09$), ($batch09$C$batch09$, $batch09$The critic never mentions alienating readers.$batch09$), ($batch09$D$batch09$, $batch09$The critic mentions an essay only to say the message deserved its own piece. How messages are developed in different forms isn't the issue.$batch09$), ($batch09$E$batch09$, $batch09$If the message didn't matter to the story's merit, there would be no reason to cut it. The critic's reason is that it actively hurts the humor.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT159-S3-Q1$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
